/**
 * Bot protection and honeypot validation utilities.
 *
 * Honeypots provide zero-friction bot deterrence:
 * Legitimate human users will not see or interact with the hidden input,
 * but automated scrapers/bots crawling and filling all form inputs will populate it.
 */

export const DEFAULT_HONEYPOT_FIELD = "_hp_auth_verification";

/**
 * Checks whether the honeypot field was populated in submitted FormData.
 * Returns `true` if submission appears to be from a legitimate human (honeypot is empty).
 * Returns `false` if submission was generated by an automated bot (honeypot populated).
 */
export function validateHoneypot(
  formData: FormData,
  fieldName: string = DEFAULT_HONEYPOT_FIELD
): boolean {
  const value = formData.get(fieldName);

  if (value === null || value === undefined) {
    // Field was not sent at all (allowed or neutral)
    return true;
  }

  if (typeof value === "string") {
    // If bot typed anything, reject
    return value.trim().length === 0;
  }

  // If a file or object was sent into the honeypot, reject
  return false;
}

/**
 * Optional timestamp-based velocity check.
 * Rejects submissions completed faster than `minDurationMs` (default: 400ms).
 */
export function validateSubmissionSpeed(
  formTimestamp: number | string | null | undefined,
  minDurationMs: number = 400
): boolean {
  if (!formTimestamp) return true;
  const parsed = typeof formTimestamp === "string" ? parseInt(formTimestamp, 10) : formTimestamp;
  if (isNaN(parsed)) return true;

  const elapsed = Date.now() - parsed;
  return elapsed >= minDurationMs;
}
